Script.Workflow:
module easy_layout_responsive;

using presentation::*;

namespace demo
{
  class EasyResponsiveAccount
  {
    prop Selected : bool = false {}
    prop Name : string = "" {}
    prop Image : INativeImage^ = null {}
  }

  class EasyResponsiveMovie
  {
    prop Title : string = "" {}
    prop Author : string = "" {}
    prop Image : INativeImage^ = null {}
  }
}

Instance.ref.Members:
var accounts : observe EasyResponsiveAccount^[] = {};
var movies : observe EasyResponsiveMovie^[] = {};

func InitializeData() : void
{
  var names : string[] = {"Penguin Random House"; "HarperCollins"; "Simon & Schuster"; "Hachette Book Group"; "Macmillan Publishers"; "Scholastic"; "Bloomsbury"; "Oxford University Press";};
  for (i in range [0, 7])
  {
    var account = new EasyResponsiveAccount^();
    account.Name = names[i];
    account.Image = (cast (GuiImageData^) self.ResolveResource("res", $"ResponsiveImages/Account$(i + 1)", true)).Image;
    self.accounts.Add(account);
  }
  /* The first 24 entries in the BFI Sight and Sound 2022 critics' poll. */
  var films : string[][] = {
    {"Jeanne Dielman, 23 quai du Commerce, 1080 Bruxelles"; "Chantal Akerman";};
    {"Vertigo"; "Alfred Hitchcock";};
    {"Citizen Kane"; "Orson Welles";};
    {"Tokyo Story"; "Yasujirō Ozu";};
    {"In the Mood for Love"; "Wong Kar-wai";};
    {"2001: A Space Odyssey"; "Stanley Kubrick";};
    {"Beau travail"; "Claire Denis";};
    {"Mulholland Dr."; "David Lynch";};
    {"Man with a Movie Camera"; "Dziga Vertov";};
    {"Singin' in the Rain"; "Stanley Donen and Gene Kelly";};
    {"Sunrise: A Song of Two Humans"; "F.W. Murnau";};
    {"The Godfather"; "Francis Ford Coppola";};
    {"La Règle du jeu"; "Jean Renoir";};
    {"Cléo from 5 to 7"; "Agnès Varda";};
    {"The Searchers"; "John Ford";};
    {"Meshes of the Afternoon"; "Maya Deren and Alexander Hammid";};
    {"Close-Up"; "Abbas Kiarostami";};
    {"Persona"; "Ingmar Bergman";};
    {"Apocalypse Now"; "Francis Ford Coppola";};
    {"Seven Samurai"; "Akira Kurosawa";};
    {"The Passion of Joan of Arc"; "Carl Theodor Dreyer";};
    {"Late Spring"; "Yasujirō Ozu";};
    {"Playtime"; "Jacques Tati";};
    {"Do the Right Thing"; "Spike Lee";};
  };
  for (i in range [0, films.Count - 1])
  {
    var movie = new EasyResponsiveMovie^();
    movie.Title = films[i][0];
    movie.Author = films[i][1];
    movie.Image = (cast (GuiImageData^) self.ResolveResource("res", "ResponsiveImages/Movie", true)).Image;
    self.movies.Add(movie);
  }
}

func InitializeItemTemplate(item : GuiListItemTemplate*, width : GuiResponsiveViewComposition*) : GuiListItemTemplate*
{
  /* Initialize before attachment: a virtual row must not raise its group's current level. */
  var view = cast (GuiResponsiveViewComposition*) item.GetNamedObject("responsiveView");
  while (view.CurrentLevel > width.CurrentLevel)
  {
    view.LevelDown();
  }
  return item;
}

func CreateMovieTemplate(value : object) : GuiListItemTemplate*
{
  return self.InitializeItemTemplate(new EasyResponsiveMovieTemplate*(cast (EasyResponsiveMovie^) value), movieWidth);
}

func CreateAccountTemplate(value : object) : GuiListItemTemplate*
{
  return self.InitializeItemTemplate(new EasyResponsiveAccountItemTemplate*(cast (EasyResponsiveAccount^) value), accountWidth);
}

BindableTextList.ev.SelectionChanged-eval:
{
                                  for (i in range [0, self.accounts.Count - 1])
                                  {
                                    self.accounts[i].Selected = accountList.GetSelected(i);
                                  }
                                }

RepeatStack.ev.ItemInserted-eval:
{
                                      var item = cast (EasyResponsiveAccountMenuTemplate*) accountMenu.StackItems[arguments.itemIndex].Children[0];
                                      var account = item.ViewModel;
                                      var button = cast (GuiToolstripButton*) item.GetNamedObject("menuButton");
                                      attach(button.Clicked, func(sender : GuiGraphicsComposition*, arguments : GuiEventArgs*) : void
                                      {
                                        accountList.SetSelected(self.accounts.IndexOf(account), true);
                                      });
                                    }
